mapper.select:
select v.id as videoId, v.category_id, v.description, v.play_url, v.cover_url, v.duration, v.title, vl.user_id is not null as is_liked, v.like_count, v.play_count, v.comment_count, v.share_count, v.status, v.created_time
from video v
left join video_like vl on vl.video_id = v.id and vl.user_id = #{userId}


    v.id < #{lastId}


    and v.user_id = #{userId}


order by v.id desc
limit #{size}

select v.id as videoId, v.user_id, u.nickname, v.like_count, v.play_url, v.cover_url, v.duration, v.title, v.created_time
from video v
join user_high u on u.id = v.user_id
join video_like vl on vl.video_id = v.id and vl.user_id = #{userId}


    v.id < #{lastId}


order by v.id desc
limit #{size}

select u.id as userId, u.nickname, u.avatar_url, u.signature, u.follow_count, u.follower_count, u.total_likes, u.role, u.created_time
from user_high u
join follow uf on uf.followee_id = u.id and uf.follower_id = #{userId}


    u.id < #{lastId}


order by u.id desc
limit #{size}

select u.id as userId, u.nickname, u.avatar_url, u.signature, u.follow_count, u.follower_count, u.total_likes, u.role, u.created_time
from user_high u
join follow uf on uf.follower_id = u.id and uf.followee_id = #{userId}


    u.id < #{lastId}


order by u.id desc
limit #{size}
